      [[-0.4,0.27],[-0.18,0.24],[0.04,0.23],[0.24,0.25],[0.42,0.28]].forEach(([x,y],i)=>{ const f = rbox(0.28,0.38,0.15,.5,hairM); f.position.set(x,y,0.5); f.rotation.z = (i-2)*0.06; head.add(f); });
