    dB:{t:[.25,.15,.35], pose:['selfie','selfie'], prop:'camera', fire:[[.25,'camFlash']], box:[1.4,3.8,3.2], dmg:6, kb:5, sc:.3, ang:45, onHit:'flashed', text:'拍照！', air:1},
