  g.fillStyle=gr; g.fillRect(2,0,12,16); g.fillStyle='#fff'; g.fillRect(6,4,1,8); g.fillRect(7,5,1,6); g.fillRect(8,6,1,4); g.fillRect(9,7,1,2);
