    dB:{t:[.2,.3,.32], pose:['block','thumbs'], fire:[[0,'jnReady']], box:[1.8,3.6,2.2], dmg:6, kb:5, sc:.3, ang:60, air:1, sfx:'jnTile', text:'聽牌了', textCls:'blue'},
