    ktScramble(a, v){ v.slowT = Math.max(v.slowT || 0, 1.8); v.meter = Math.max(0, v.meter - 8); pop('接不到！', v.x, v.y+7.5, 'blue'); burst(v.x, v.y+4, 0xffe066, 6, 5); },
