const pdSockTex = tex(16,16,(g)=>{ speckle(g,16,16,'#f6f6f2',['#eceae4','#fdfdfa'],.3); g.fillStyle='rgba(190,190,182,.5)'; for (let x=0;x<16;x+=3) g.fillRect(x,0,1,16); });

