  g.add(at(new THREE.Mesh(new THREE.BoxGeometry(0.9,1.1,0.1), d),-1.8,0.6,0));
  g.add(at(new THREE.Mesh(new THREE.BoxGeometry(0.7,0.08,1.8), d),-1.9,0.1,0));
