  g.add(at(new THREE.Mesh(new THREE.BoxGeometry(1.7,0.18,1.5), seatM),0,1.95,0));
  g.add(at(new THREE.Mesh(new THREE.BoxGeometry(1.7,1.6,0.14), seatM),0,2.8,-0.72));
