  g.fillStyle = TMIL_WHITE; g.beginPath(); g.moveTo(21,56); g.lineTo(43,56); g.lineTo(32,64); g.closePath(); g.fill();
  g.fillStyle = TMIL_GOLD_L; g.fillRect(31,59,2,2);
